using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using HotChocolate;
using HotChocolate.Types;
using System.Data.SqlClient;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace InternalReportingApi
{
    public class Program
    {
        public static void Main(string[] args)
        {
            CreateHostBuilder(args).Build().Run();
        }

        public static IHostBuilder CreateHostBuilder(string[] args) =>
            Host.CreateDefaultBuilder(args)
                .ConfigureWebHostDefaults(webBuilder =>
                {
                    webBuilder.UseStartup<Startup>();
                });
    }

    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddGraphQLServer()
                .AddQueryType<Query>()
                .AddMutationType<Mutation>();
            services.AddSingleton<ReportRepository>();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseRouting();
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapGraphQL();
            });
        }
    }

    public class Report
    {
        public int Id { get; set; }
        public string Title { get; set; }
        public string Content { get; set; }
        public string Author { get; set; }
        public string Classification { get; set; }
    }

    public class ReportRepository
    {
        private readonly string _connectionString = 
            "Server=db-internal.corp.local;Database=Reports;Integrated Security=true;";

        // Used by internal dashboards for flexible report filtering
        public async Task<List<Report>> SearchReports(string filterExpression)
        {
            var reports = new List<Report>();
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            // filterExpression comes from GraphQL resolver - trusted internal callers only
            var query = $"SELECT Id, Title, Content, Author, Classification FROM Reports WHERE {filterExpression}";

            using var command = new SqlCommand(query, connection);
            using var reader = await command.ExecuteReaderAsync();
            while (await reader.ReadAsync())
            {
                reports.Add(new Report
                {
                    Id = reader.GetInt32(0),
                    Title = reader.GetString(1),
                    Content = reader.GetString(2),
                    Author = reader.GetString(3),
                    Classification = reader.GetString(4)
                });
            }
            return reports;
        }

        public async Task<bool> UpdateClassification(int reportId, string newClassification)
        {
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();
            var query = $"UPDATE Reports SET Classification = '{newClassification}' WHERE Id = {reportId}";
            using var command = new SqlCommand(query, connection);
            return await command.ExecuteNonQueryAsync() > 0;
        }
    }

    public class Query
    {
        public async Task<List<Report>> GetReports(
            [Service] ReportRepository repo,
            string? author,
            string? classification,
            string? customFilter)
        {
            string filter;
            if (!string.IsNullOrEmpty(customFilter))
            {
                // Power-user filter for internal analytics team
                filter = customFilter;
            }
            else
            {
                var conditions = new List<string> { "1=1" };
                if (!string.IsNullOrEmpty(author))
                    conditions.Add($"Author = '{author}'");
                if (!string.IsNullOrEmpty(classification))
                    conditions.Add($"Classification = '{classification}'");
                filter = string.Join(" AND ", conditions);
            }
            return await repo.SearchReports(filter);
        }
    }

    public class Mutation
    {
        public async Task<bool> ReclassifyReport(
            [Service] ReportRepository repo,
            int reportId,
            string newClassification)
        {
            return await repo.UpdateClassification(reportId, newClassification);
        }
    }
}
